//go:build integration

// G013 B-RETENTION-IT (Plan r3 §6, §10.1 RT-1..9, §11.6 E-RET-1..3): TestRetention against the disposable PostgreSQL at
// version 9 with the actual retention login (<db>_retention over TCP with DB_RETENTION_PASSWORD, attested: not
// superuser, no BYPASSRLS, a member of nothing). The world holds old, recent, held, foreign and global audit rows and
// tombstones in every lifecycle state, generated by trigger-owned row changes, the global anonymous sign-in-failure shape
// and superuser-seeded tombstone rows without bytes; fixtures and every expectation use the attested superuser. Prints
// E-RET-1..3 (and E-RET-TRIGGER for an unexpected relation or lock) for the harness; never a benchmark.
//
// Required environment: the B-POLICY-IT settings plus DB_RETENTION_PASSWORD.
package access

import (
	"context"
	"encoding/json"
	"fmt"
	"os"
	"slices"
	"strings"
	"testing"
	"time"

	"github.com/jackc/pgx/v5"
)

const retTimeLayout = "2006-01-02T15:04:05.000000Z"

func retCut(at time.Time) string { return at.UTC().Format(retTimeLayout) }

// retConn is the actual retention login, attested before use.
func (e *itEnv) retConn(t *testing.T) *pgx.Conn {
	t.Helper()
	pw := os.Getenv("DB_RETENTION_PASSWORD")
	if pw == "" {
		t.Fatal("integration settings: DB_RETENTION_PASSWORD is required for B-RETENTION-IT")
	}
	c := itConnect(t, e.cfg, e.cfg.RetentionRole(), pw)
	var got string
	if err := c.QueryRow(context.Background(), `SELECT format('%s|%s|%s|%s|%s', session_user, current_user, r.rolsuper, r.rolbypassrls,
  (SELECT count(*) FROM pg_auth_members m WHERE m.member = r.oid)) FROM pg_roles r WHERE r.rolname = current_user`).Scan(&got); err != nil ||
		got != e.cfg.RetentionRole()+"|"+e.cfg.RetentionRole()+"|f|f|0" {
		t.Fatalf("retention attestation: %q (%v)", got, err)
	}
	return c
}

// retSettings sets the three transaction-local retention settings in tx.
func retSettings(t *testing.T, tx pgx.Tx, scope, cutoff, holds string) {
	t.Helper()
	if _, err := tx.Exec(context.Background(), `SELECT set_config('retention.scope', $1, true), set_config('retention.cutoff', $2, true),
  set_config('retention.holds', $3, true)`, scope, cutoff, holds); err != nil {
		t.Fatal(err)
	}
}

// retWorld is the pinned synthetic distribution (§10.1 RT-9) plus the lifecycle controls.
type retWorld struct {
	orgA, orgB, held, other string
	tMid, tObj              time.Time
	tombEligible            string // one eligible deleted tombstone of A
}

func (e *itEnv) retNow(t *testing.T) time.Time {
	t.Helper()
	var at time.Time
	if err := e.setup.QueryRow(context.Background(), `SELECT clock_timestamp()`).Scan(&at); err != nil {
		t.Fatal(err)
	}
	return at
}

func (e *itEnv) retExec(t *testing.T, sql string, args ...any) {
	t.Helper()
	if _, err := e.setup.Exec(context.Background(), sql, args...); err != nil {
		t.Fatalf("fixture: %v", err)
	}
}

// retBuild generates the distribution: Organization A about 4,000 events before T_mid (about 200 naming the held user)
// and 1,000 after; Organization B about 1,000; global about 2,000 before and 500 after; about 200 tombstones in A (50
// held, 50 after the object cutoff) and 50 in B, plus one ready, pending and deleting row in A. All superuser fixtures.
func (e *itEnv) retBuild(t *testing.T) retWorld {
	t.Helper()
	var w retWorld
	w.orgA, w.orgB = e.org(t, "Retention A "+e.canaries[0]).String(), e.org(t, "Retention B").String()
	// The fixture rows have no bytes; they are removed at the end (as every object test cleans its rows), so later
	// version steps of the suite are not refused by 00007's down.
	t.Cleanup(func() {
		_, _ = e.setup.Exec(context.Background(), `DELETE FROM app.stored_objects WHERE organization_id IN ($1::uuid, $2::uuid)`, w.orgA, w.orgB)
	})
	if err := e.setup.QueryRow(context.Background(), `INSERT INTO app.users (display_name) VALUES ('Retention Held') RETURNING id::text`).Scan(&w.held); err != nil {
		t.Fatal(err)
	}
	if err := e.setup.QueryRow(context.Background(), `INSERT INTO app.users (display_name) VALUES ('Retention Other') RETURNING id::text`).Scan(&w.other); err != nil {
		t.Fatal(err)
	}
	// Before T_mid: 3,800 renames of A (organization.renamed), 100 grant/remove cycles of the held user in A (200
	// membership rows naming it), 1,000 renames of B and 2,000 global anonymous sign-in failures.
	e.retExec(t, `DO $$ BEGIN FOR i IN 1..3800 LOOP UPDATE app.organizations SET name = 'Retention A ' || i WHERE id = '`+w.orgA+`'; END LOOP; END $$`)
	e.retExec(t, `DO $$ BEGIN FOR i IN 1..100 LOOP
  INSERT INTO app.role_bindings (organization_id, subject_user_id, scope_type, scope_id, role, source)
  VALUES ('`+w.orgA+`', '`+w.held+`', 'organization', '`+w.orgA+`', 'org_member', 'membership');
  DELETE FROM app.role_bindings WHERE organization_id = '`+w.orgA+`' AND subject_user_id = '`+w.held+`'; END LOOP; END $$`)
	e.retExec(t, `DO $$ BEGIN FOR i IN 1..1000 LOOP UPDATE app.organizations SET name = 'Retention B ' || i WHERE id = '`+w.orgB+`'; END LOOP; END $$`)
	e.retExec(t, `DO $$ BEGIN FOR i IN 1..2000 LOOP
  INSERT INTO audit.events (action, outcome, reason) VALUES ('auth.sign_in', 'denied', 'code_rejected'); END LOOP; END $$`)
	time.Sleep(20 * time.Millisecond)
	w.tMid = e.retNow(t)
	time.Sleep(20 * time.Millisecond)
	e.retExec(t, `DO $$ BEGIN FOR i IN 1..1000 LOOP UPDATE app.organizations SET name = 'Retention A late ' || i WHERE id = '`+w.orgA+`'; END LOOP; END $$`)
	e.retExec(t, `DO $$ BEGIN FOR i IN 1..500 LOOP
  INSERT INTO audit.events (action, outcome, reason) VALUES ('auth.sign_in', 'denied', 'code_rejected'); END LOOP; END $$`)
	// Tombstones (rows only; no bytes): deleted_at is a fixture value relative to the object cutoff T_obj = now - 1 h.
	w.tObj = e.retNow(t).Add(-time.Hour)
	e.retExec(t, `INSERT INTO app.stored_objects (id, organization_id, group_id, creator_user_id, state, byte_size, content_type, sha256,
  ready_at, deleting_at, deleted_at, deleted_by)
SELECT gen_random_uuid(), o, NULL, c, 'deleted', 1, 'text/plain', sha256('t'::bytea), d, d, d, b
FROM (SELECT $1::uuid AS o, $3::uuid AS c, $4::uuid AS b, now() - interval '3 hours' AS d FROM generate_series(1, 100)
      UNION ALL SELECT $1::uuid, $3::uuid, $5::uuid, now() - interval '3 hours' FROM generate_series(1, 50)
      UNION ALL SELECT $1::uuid, $3::uuid, $4::uuid, now() FROM generate_series(1, 50)
      UNION ALL SELECT $2::uuid, $3::uuid, $4::uuid, now() - interval '3 hours' FROM generate_series(1, 50)) s`,
		w.orgA, w.orgB, w.other, w.other, w.held)
	for _, st := range []string{"ready", "pending", "deleting"} {
		e.retExec(t, `INSERT INTO app.stored_objects (id, organization_id, creator_user_id, state, byte_size, content_type, sha256, ready_at,
  deleting_at, deleted_by) VALUES (gen_random_uuid(), $1::uuid, $2::uuid, $3, 1, 'text/plain',
  CASE WHEN $3 = 'pending' THEN NULL ELSE sha256('t'::bytea) END, CASE WHEN $3 = 'pending' THEN NULL ELSE now() - interval '3 hours' END,
  CASE WHEN $3 = 'deleting' THEN now() - interval '3 hours' END, CASE WHEN $3 = 'deleting' THEN $2::uuid END)`, w.orgA, w.other, st)
	}
	if err := e.setup.QueryRow(context.Background(), `SELECT id::text FROM app.stored_objects WHERE organization_id = $1::uuid AND state = 'deleted'
  AND deleted_by = $2::uuid AND deleted_at < $3 ORDER BY id LIMIT 1`, w.orgA, w.other, w.tObj).Scan(&w.tombEligible); err != nil {
		t.Fatal(err)
	}
	e.retExec(t, `ANALYZE audit.events, app.stored_objects`)
	return w
}

// retCount is a superuser count of audit rows matching where (an independent predicate over the fixture).
func (e *itEnv) retCount(t *testing.T, where string, args ...any) int {
	t.Helper()
	var n int
	if err := e.setup.QueryRow(context.Background(), `SELECT count(*)::int FROM audit.events WHERE `+where, args...).Scan(&n); err != nil {
		t.Fatal(err)
	}
	return n
}

// retCatalog fingerprints the retention-relevant catalog (policies, ACLs, triggers, function bodies) for the
// unchanged-after checks.
func (e *itEnv) retCatalog(t *testing.T) string {
	t.Helper()
	var s string
	if err := e.setup.QueryRow(context.Background(), `SELECT md5(
  coalesce((SELECT string_agg(polname || pg_get_expr(polqual, polrelid) || polroles::text, ',' ORDER BY polname) FROM pg_policy), '') ||
  coalesce((SELECT string_agg(c.relname || coalesce(c.relacl::text, '-'), ',' ORDER BY c.relname) FROM pg_class c
            WHERE c.relnamespace IN ('app'::regnamespace, 'audit'::regnamespace)), '') ||
  coalesce((SELECT string_agg(tgname || tgenabled::text, ',' ORDER BY tgname) FROM pg_trigger WHERE NOT tgisinternal), '') ||
  coalesce((SELECT string_agg(proname || md5(prosrc) || coalesce(proacl::text, '-'), ',' ORDER BY proname) FROM pg_proc
            WHERE pronamespace IN ('app'::regnamespace, 'audit'::regnamespace)), ''))`).Scan(&s); err != nil {
		t.Fatal(err)
	}
	return s
}

func retState(err error) string {
	if p := pgErr(err); p != nil {
		return p.Code
	}
	if err != nil {
		return "error"
	}
	return "ok"
}

// retPlan is one E-RET observation: the plan nodes, the relations and indexes used, rows and buffers, and timing.
type retPlan struct {
	Name, Statement string
	Nodes           []string
	Relations       []string
	Indexes         []string
	RowsOut         float64
	RowsFiltered    float64
	SharedHit       float64
	SharedRead      float64
	ExecMS          float64
	Fixture         map[string]int
	Locks           []string `json:",omitempty"`
}

func walkPlan(n map[string]any, p *retPlan) {
	if s, _ := n["Node Type"].(string); s != "" {
		p.Nodes = append(p.Nodes, s)
	}
	if s, _ := n["Relation Name"].(string); s != "" && !slices.Contains(p.Relations, s) {
		p.Relations = append(p.Relations, s)
	}
	if s, _ := n["Index Name"].(string); s != "" && !slices.Contains(p.Indexes, s) {
		p.Indexes = append(p.Indexes, s)
	}
	if v, ok := n["Rows Removed by Filter"].(float64); ok {
		p.RowsFiltered += v
	}
	if sub, ok := n["Plans"].([]any); ok {
		for _, s := range sub {
			if m, ok := s.(map[string]any); ok {
				walkPlan(m, p)
			}
		}
	}
}

// retExplain runs EXPLAIN (ANALYZE, BUFFERS, FORMAT JSON) of stmt as the retention login inside a rolled-back
// transaction with the given settings and returns the observation (with the lock inventory when locks is set).
func (e *itEnv) retExplain(t *testing.T, rc *pgx.Conn, name, scope, cutoff, holds, stmt string, locks bool) retPlan {
	t.Helper()
	ctx := context.Background()
	tx, err := rc.Begin(ctx)
	if err != nil {
		t.Fatal(err)
	}
	defer func() { _ = tx.Rollback(ctx) }()
	retSettings(t, tx, scope, cutoff, holds)
	var raw []byte
	if err := tx.QueryRow(ctx, `EXPLAIN (ANALYZE, BUFFERS, FORMAT JSON) `+stmt).Scan(&raw); err != nil {
		t.Fatalf("%s explain: %v", name, err)
	}
	var doc []map[string]any
	if err := json.Unmarshal(raw, &doc); err != nil || len(doc) != 1 {
		t.Fatalf("%s plan: %v", name, err)
	}
	shown := stmt
	if i := strings.Index(shown, "ARRAY['"); i >= 0 {
		shown = shown[:i] + "ARRAY[<" + fmt.Sprint(strings.Count(shown, "'")/2) + " confirmed ids>]::uuid[])"
	}
	p := retPlan{Name: name, Statement: shown}
	top, _ := doc[0]["Plan"].(map[string]any)
	walkPlan(top, &p)
	p.RowsOut, _ = top["Actual Rows"].(float64)
	// A DELETE without RETURNING emits no rows: report the rows its input produced (the rows deleted).
	if nt, _ := top["Node Type"].(string); nt == "ModifyTable" {
		if sub, ok := top["Plans"].([]any); ok && len(sub) > 0 {
			if m, ok := sub[0].(map[string]any); ok {
				p.RowsOut, _ = m["Actual Rows"].(float64)
			}
		}
	}
	p.SharedHit, _ = top["Shared Hit Blocks"].(float64)
	p.SharedRead, _ = top["Shared Read Blocks"].(float64)
	p.ExecMS, _ = doc[0]["Execution Time"].(float64)
	if locks {
		rows, err := tx.Query(ctx, `SELECT format('%s:%s', c.relname, l.mode) FROM pg_locks l JOIN pg_class c ON c.oid = l.relation
WHERE l.pid = pg_backend_pid() AND l.locktype = 'relation' AND c.relnamespace IN ('app'::regnamespace, 'audit'::regnamespace) ORDER BY 1`)
		if err != nil {
			t.Fatal(err)
		}
		for rows.Next() {
			var s string
			if err := rows.Scan(&s); err != nil {
				t.Fatal(err)
			}
			p.Locks = append(p.Locks, s)
		}
		rows.Close()
	}
	return p
}

func retPrint(t *testing.T, p retPlan, allowedRelations []string) {
	t.Helper()
	b, _ := json.Marshal(p)
	fmt.Println(p.Name + " " + string(b))
	var unexpected []string
	for _, r := range p.Relations {
		if !slices.Contains(allowedRelations, r) {
			unexpected = append(unexpected, "relation:"+r)
		}
	}
	for _, l := range p.Locks {
		rel := strings.SplitN(l, ":", 2)[0]
		if !slices.Contains(allowedRelations, rel) && !strings.HasPrefix(rel, "stored_objects_") && !strings.HasPrefix(rel, "events_") {
			unexpected = append(unexpected, "lock:"+l)
		}
	}
	if len(unexpected) > 0 {
		b, _ := json.Marshal(map[string]any{"observation": p.Name, "unexpected": unexpected})
		fmt.Println("E-RET-TRIGGER " + string(b))
	}
}

// TestRetention (B-RETENTION-IT): RT-1..9.
func TestRetention(t *testing.T) {
	e := setupIT(t)
	ctx := context.Background()
	w := e.retBuild(t)
	rc := e.retConn(t)
	scopeA := "organization:" + w.orgA
	cutMid, cutObj := retCut(w.tMid), retCut(w.tObj)
	heldWhere := `ARRAY[organization_id, group_id, actor_user_id, subject_user_id, resource_id] && ARRAY[$2::uuid]`

	// count runs one statement as the retention login in a fresh transaction with the settings (scope "" = none).
	count := func(t *testing.T, scope, cutoff, holds, sql string, args ...any) (int, error) {
		t.Helper()
		tx, err := rc.Begin(ctx)
		if err != nil {
			t.Fatal(err)
		}
		defer func() { _ = tx.Rollback(ctx) }()
		if scope != "-" {
			retSettings(t, tx, scope, cutoff, holds)
		}
		var n int
		err = tx.QueryRow(ctx, sql, args...).Scan(&n)
		return n, err
	}
	del := func(t *testing.T, scope, cutoff, holds, sql string, args ...any) (int64, error) {
		t.Helper()
		tx, err := rc.Begin(ctx)
		if err != nil {
			t.Fatal(err)
		}
		retSettings(t, tx, scope, cutoff, holds)
		tag, err := tx.Exec(ctx, sql, args...)
		if err != nil {
			_ = tx.Rollback(ctx)
			return 0, err
		}
		return tag.RowsAffected(), tx.Commit(ctx)
	}

	t.Run("RT-1 absent settings raise on SELECT and DELETE", func(t *testing.T) {
		fresh := e.retConn(t)
		for _, sql := range []string{`SELECT count(*) FROM audit.events`, `SELECT count(*) FROM app.stored_objects`} {
			var n int
			if err := fresh.QueryRow(ctx, sql).Scan(&n); retState(err) != "22023" {
				t.Errorf("fresh %q: %v (want 22023)", sql, err)
			}
		}
		if _, err := fresh.Exec(ctx, `DELETE FROM audit.events WHERE organization_id = $1::uuid`, w.orgA); retState(err) != "22023" {
			t.Errorf("fresh DELETE: %v (want 22023)", err)
		}
		// After a transaction that set them, the placeholders reset to empty: still absent.
		if _, err := count(t, scopeA, cutMid, "none", `SELECT count(*) FROM audit.events`); err != nil {
			t.Fatalf("with settings: %v", err)
		}
		if _, err := count(t, "-", "", "", `SELECT count(*) FROM audit.events`); retState(err) != "22023" {
			t.Errorf("after a reset: %v (want 22023)", err)
		}
		if _, err := count(t, "-", "", "", `SELECT count(*) FROM app.stored_objects`); retState(err) != "22023" {
			t.Errorf("tombstones after a reset: %v (want 22023)", err)
		}
	})

	t.Run("RT-2 malformed settings raise", func(t *testing.T) {
		var future, present string
		future = retCut(e.retNow(t).Add(time.Hour))
		many := make([]string, 257)
		for i := range many {
			many[i] = w.held
		}
		for _, c := range []struct{ what, scope, cutoff, holds string }{
			{"scope not a uuid", "organization:not-a-uuid", cutMid, "none"},
			{"scope kind", "tenant:" + w.orgA, cutMid, "none"},
			{"scope uppercase", "organization:" + strings.ToUpper(w.orgA), cutMid, "none"},
			{"cutoff future", scopeA, future, "none"},
			{"cutoff format", scopeA, w.tMid.Format(time.RFC1123), "none"},
			{"cutoff month", scopeA, "2026-13-01T00:00:00Z", "none"},
			{"holds empty string", scopeA, cutMid, ""},
			{"holds garbage", scopeA, cutMid, "abc"},
			{"holds oversized", scopeA, cutMid, strings.Join(many, ",")},
			{"holds trailing comma", scopeA, cutMid, w.held + ","},
		} {
			if _, err := count(t, c.scope, c.cutoff, c.holds, `SELECT count(*) FROM audit.events`); retState(err) != "22023" {
				t.Errorf("%s: %v (want 22023)", c.what, err)
			}
		}
		// The present: the cutoff equal to the transaction time.
		tx, err := rc.Begin(ctx)
		if err != nil {
			t.Fatal(err)
		}
		if err := tx.QueryRow(ctx, `SELECT to_char(transaction_timestamp() AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.US"Z"')`).Scan(&present); err != nil {
			t.Fatal(err)
		}
		retSettings(t, tx, scopeA, present, "none")
		var n int
		if err := tx.QueryRow(ctx, `SELECT count(*) FROM audit.events`).Scan(&n); retState(err) != "22023" {
			t.Errorf("present cutoff: %v (want 22023)", err)
		}
		_ = tx.Rollback(ctx)
		// 256 holds are accepted.
		if _, err := count(t, scopeA, cutMid, strings.Join(many[:256], ","), `SELECT count(*) FROM audit.events`); err != nil {
			t.Errorf("256 holds: %v", err)
		}
	})

	t.Run("RT-9 E-RET-1..3 bounded observations", func(t *testing.T) {
		fix := map[string]int{
			"org_a_before":  e.retCount(t, `organization_id = $1::uuid AND occurred_at < $2`, w.orgA, w.tMid),
			"org_a_after":   e.retCount(t, `organization_id = $1::uuid AND occurred_at >= $2`, w.orgA, w.tMid),
			"org_a_held":    e.retCount(t, `organization_id = $1::uuid AND occurred_at < $3 AND `+heldWhere, w.orgA, w.held, w.tMid),
			"org_b":         e.retCount(t, `organization_id = $1::uuid`, w.orgB),
			"global_before": e.retCount(t, `organization_id IS NULL AND occurred_at < $1`, w.tMid),
			"global_after":  e.retCount(t, `organization_id IS NULL AND occurred_at >= $1`, w.tMid),
			"events_total":  e.retCount(t, `true`),
		}
		var tombs int
		if err := e.setup.QueryRow(ctx, `SELECT count(*)::int FROM app.stored_objects WHERE organization_id IN ($1::uuid, $2::uuid)`, w.orgA, w.orgB).Scan(&tombs); err != nil {
			t.Fatal(err)
		}
		fix["stored_objects_fixture"] = tombs
		orgDel := fmt.Sprintf(`DELETE FROM audit.events WHERE id IN (SELECT id FROM audit.events WHERE organization_id = '%s' AND occurred_at < '%s' ORDER BY occurred_at, id LIMIT 500)`, w.orgA, cutMid)
		orgCount := fmt.Sprintf(`SELECT count(*) FROM audit.events WHERE organization_id = '%s' AND occurred_at < '%s'`, w.orgA, cutMid)
		globDel := fmt.Sprintf(`DELETE FROM audit.events WHERE id IN (SELECT id FROM audit.events WHERE organization_id IS NULL AND occurred_at < '%s' ORDER BY occurred_at, id LIMIT 500)`, cutMid)
		globCount := fmt.Sprintf(`SELECT count(*) FROM audit.events WHERE organization_id IS NULL AND occurred_at < '%s'`, cutMid)
		cand := fmt.Sprintf(`SELECT id FROM app.stored_objects WHERE organization_id = '%s' AND state = 'deleted' AND deleted_at < '%s' ORDER BY deleted_at, id LIMIT 500`, w.orgA, cutObj)
		holds := w.held
		for _, o := range []struct {
			name, scope, stmt string
			rel               []string
			locks             bool
		}{
			{"E-RET-1", scopeA, orgDel, []string{"events"}, true},
			{"E-RET-1-COUNT", scopeA, orgCount, []string{"events"}, false},
			{"E-RET-2", "global", globDel, []string{"events"}, true},
			{"E-RET-2-COUNT", "global", globCount, []string{"events"}, false},
			{"E-RET-3-CANDIDATES", scopeA, cand, []string{"stored_objects"}, false},
		} {
			cut := cutMid
			if strings.HasPrefix(o.name, "E-RET-3") {
				cut = cutObj
			}
			p := e.retExplain(t, rc, o.name, o.scope, cut, holds, o.stmt, o.locks)
			p.Fixture = fix
			retPrint(t, p, o.rel)
		}
		// E-RET-3 DELETE of the confirmed IDs (the candidates' first 100), with its lock inventory.
		rows, err := e.setup.Query(ctx, `SELECT id::text FROM app.stored_objects WHERE organization_id = $1::uuid AND state = 'deleted'
  AND deleted_at < $2 AND deleted_by <> $3::uuid ORDER BY deleted_at, id LIMIT 100`, w.orgA, w.tObj, w.held)
		if err != nil {
			t.Fatal(err)
		}
		var ids []string
		for rows.Next() {
			var s string
			_ = rows.Scan(&s)
			ids = append(ids, "'"+s+"'")
		}
		rows.Close()
		p := e.retExplain(t, rc, "E-RET-3", scopeA, cutObj, holds,
			`DELETE FROM app.stored_objects WHERE id = ANY (ARRAY[`+strings.Join(ids, ",")+`]::uuid[])`, true)
		p.Fixture = fix
		retPrint(t, p, []string{"stored_objects"})
		if p.RowsOut != 0 && len(ids) != 100 {
			t.Errorf("E-RET-3 confirmed ids %d", len(ids))
		}
		if e.retCount(t, `true`) != fix["events_total"] {
			t.Error("the observations changed audit rows (they must roll back)")
		}
	})

	t.Run("RT-3 Organization scope deletes exactly the eligible set", func(t *testing.T) {
		eligible := e.retCount(t, `organization_id = $1::uuid AND occurred_at < $3 AND NOT (`+heldWhere+`)`, w.orgA, w.held, w.tMid)
		heldBefore := e.retCount(t, `organization_id = $1::uuid AND occurred_at < $3 AND `+heldWhere, w.orgA, w.held, w.tMid)
		recentA := e.retCount(t, `organization_id = $1::uuid AND occurred_at >= $2`, w.orgA, w.tMid)
		b := e.retCount(t, `organization_id = $1::uuid`, w.orgB)
		global := e.retCount(t, `organization_id IS NULL`)
		if eligible < 3800 || heldBefore < 200 {
			t.Fatalf("fixture: eligible %d, held %d", eligible, heldBefore)
		}
		if n, err := count(t, scopeA, cutMid, w.held, `SELECT count(*) FROM audit.events`); err != nil || n != eligible {
			t.Fatalf("visible %d (%v), want %d", n, err, eligible)
		}
		got, err := del(t, scopeA, cutMid, w.held, `DELETE FROM audit.events WHERE organization_id = $1::uuid AND occurred_at < $2`, w.orgA, w.tMid)
		if err != nil || got != int64(eligible) {
			t.Fatalf("deleted %d (%v), want %d", got, err, eligible)
		}
		if n := e.retCount(t, `organization_id = $1::uuid AND occurred_at < $2`, w.orgA, w.tMid); n != heldBefore {
			t.Errorf("A before T_mid left %d rows, want exactly the %d held", n, heldBefore)
		}
		if e.retCount(t, `organization_id = $1::uuid AND occurred_at >= $2`, w.orgA, w.tMid) != recentA ||
			e.retCount(t, `organization_id = $1::uuid`, w.orgB) != b || e.retCount(t, `organization_id IS NULL`) != global {
			t.Error("recent, foreign or global rows changed")
		}
		// Bounded batches: the tool's exact statement deletes at most its batch, oldest first, and nothing more is eligible.
		if got, err := del(t, scopeA, cutMid, w.held, `DELETE FROM audit.events WHERE id IN (SELECT id FROM audit.events
  WHERE organization_id = $1::uuid AND occurred_at < $2 ORDER BY occurred_at, id LIMIT 2)`, w.orgA, w.tMid); err != nil || got != 0 {
			t.Errorf("repeat batch deleted %d (%v)", got, err)
		}
	})

	t.Run("RT-4 global scope deletes only eligible global rows", func(t *testing.T) {
		eligible := e.retCount(t, `organization_id IS NULL AND occurred_at < $1 AND NOT (ARRAY[organization_id, group_id, actor_user_id,
  subject_user_id, resource_id] && ARRAY[$2::uuid])`, w.tMid, w.held)
		recent := e.retCount(t, `organization_id IS NULL AND occurred_at >= $1`, w.tMid)
		orgRows := e.retCount(t, `organization_id IS NOT NULL`)
		if eligible < 2000 {
			t.Fatalf("fixture: eligible global %d", eligible)
		}
		got, err := del(t, "global", cutMid, w.held, `DELETE FROM audit.events WHERE id IN (SELECT id FROM audit.events
  WHERE organization_id IS NULL AND occurred_at < $1 ORDER BY occurred_at, id LIMIT 1000)`, w.tMid)
		if err != nil || got != 1000 {
			t.Fatalf("first global batch %d (%v)", got, err)
		}
		got2, err := del(t, "global", cutMid, w.held, `DELETE FROM audit.events WHERE organization_id IS NULL AND occurred_at < $1`, w.tMid)
		if err != nil || got+got2 != int64(eligible) {
			t.Fatalf("global deleted %d+%d (%v), want %d", got, got2, err, eligible)
		}
		if e.retCount(t, `organization_id IS NULL AND occurred_at >= $1`, w.tMid) != recent || e.retCount(t, `organization_id IS NOT NULL`) != orgRows {
			t.Error("recent global or Organization rows changed")
		}
	})

	t.Run("RT-5 forbidden statements refused with rows and catalog unchanged", func(t *testing.T) {
		before, rows := e.retCatalog(t), e.retCount(t, `true`)
		for _, s := range []string{
			`UPDATE audit.events SET outcome = 'failed'`,
			`TRUNCATE audit.events`,
			`INSERT INTO audit.events (action, outcome, reason) VALUES ('auth.sign_in', 'denied', 'code_rejected')`,
			`ALTER TABLE audit.events NO FORCE ROW LEVEL SECURITY`,
			`CREATE TABLE audit.retention_ddl (id int)`,
			`CREATE TABLE app.retention_ddl (id int)`,
			`GRANT DELETE ON audit.events TO PUBLIC`,
			`SET ROLE ` + pgx.Identifier{e.cfg.OwnerRole()}.Sanitize(),
			`ALTER TABLE audit.events DISABLE TRIGGER events_refuse`,
			`SET LOCAL row_security = off; SELECT count(*) FROM audit.events`,
			`UPDATE app.stored_objects SET state = 'deleted'`,
			`DELETE FROM app.users`,
			`SELECT count(*) FROM app.organizations`,
		} {
			tx, err := rc.Begin(ctx)
			if err != nil {
				t.Fatal(err)
			}
			retSettings(t, tx, scopeA, cutMid, "none")
			_, err = tx.Exec(ctx, s)
			_ = tx.Rollback(ctx)
			// A GRANT of a privilege held without grant option grants nothing (a warning); the catalog check below proves it.
			if retState(err) != "42501" && !(strings.HasPrefix(s, "GRANT") && err == nil) {
				t.Errorf("retention %q: %v (want 42501)", s, err)
			}
		}
		// The GRANT once more, committed: still nothing granted.
		if _, err := rc.Exec(ctx, `GRANT DELETE ON audit.events TO PUBLIC`); err != nil && retState(err) != "42501" {
			t.Errorf("committed GRANT: %v", err)
		}
		if e.retCatalog(t) != before || e.retCount(t, `true`) != rows {
			t.Error("catalog or rows changed")
		}
	})

	t.Run("RT-6 runtime, owner and superuser stay unable to delete history", func(t *testing.T) {
		rows := e.retCount(t, `true`)
		rt := itConnect(t, e.cfg, e.cfg.RuntimeRole(), e.pw)
		for _, s := range []string{`DELETE FROM audit.events`, `UPDATE audit.events SET outcome = 'failed'`, `TRUNCATE audit.events`,
			`DELETE FROM app.stored_objects`} {
			tx, err := rt.Begin(ctx)
			if err != nil {
				t.Fatal(err)
			}
			retSettings(t, tx, scopeA, cutMid, "none")
			_, err = tx.Exec(ctx, s)
			_ = tx.Rollback(ctx)
			if retState(err) != "42501" {
				t.Errorf("runtime %q: %v (want 42501)", s, err)
			}
		}
		own := itConnect(t, e.cfg, e.cfg.MigratorRole(), e.cfg.Password)
		if _, err := own.Exec(ctx, `SET ROLE `+pgx.Identifier{e.cfg.OwnerRole()}.Sanitize()); err != nil {
			t.Fatal(err)
		}
		for _, s := range []string{`DELETE FROM audit.events`, `UPDATE audit.events SET outcome = 'failed'`, `DELETE FROM app.stored_objects`} {
			tx, err := own.Begin(ctx)
			if err != nil {
				t.Fatal(err)
			}
			retSettings(t, tx, scopeA, cutMid, "none")
			tag, err := tx.Exec(ctx, s)
			_ = tx.Rollback(ctx)
			if err != nil || tag.RowsAffected() != 0 {
				t.Errorf("owner %q: %d rows (%v), want 0", s, tag.RowsAffected(), err)
			}
		}
		if _, err := own.Exec(ctx, `TRUNCATE audit.events`); retState(err) != "42501" {
			t.Errorf("owner TRUNCATE: %v (want the append-only refusal)", err)
		}
		// The superuser: row-level security does not apply, the refusal does (the exception is role-bound), even with an
		// eligible declaration.
		tx, err := e.setup.Begin(ctx)
		if err != nil {
			t.Fatal(err)
		}
		retSettings(t, tx, "global", cutMid, "none")
		_, err = tx.Exec(ctx, `DELETE FROM audit.events WHERE id = (SELECT id FROM audit.events WHERE organization_id IS NULL ORDER BY occurred_at LIMIT 1)`)
		_ = tx.Rollback(ctx)
		if retState(err) != "42501" || !strings.Contains(err.Error(), "append-only") {
			t.Errorf("superuser DELETE: %v (want append-only)", err)
		}
		if e.retCount(t, `true`) != rows {
			t.Error("rows changed")
		}
	})

	t.Run("RT-7 tombstones: only eligible deleted rows are visible and deletable", func(t *testing.T) {
		var eligible, others int
		if err := e.setup.QueryRow(ctx, `SELECT count(*) FILTER (WHERE organization_id = $1::uuid AND state = 'deleted' AND deleted_at < $3 AND deleted_by <> $4::uuid)::int,
  count(*) FILTER (WHERE NOT (organization_id = $1::uuid AND state = 'deleted' AND deleted_at < $3 AND deleted_by <> $4::uuid))::int
FROM app.stored_objects WHERE organization_id IN ($1::uuid, $2::uuid)`, w.orgA, w.orgB, w.tObj, w.held).Scan(&eligible, &others); err != nil {
			t.Fatal(err)
		}
		if eligible != 100 || others != 153 {
			t.Fatalf("fixture: eligible %d, others %d", eligible, others)
		}
		if n, err := count(t, scopeA, cutObj, w.held, `SELECT count(*) FROM app.stored_objects`); err != nil || n != eligible {
			t.Fatalf("visible tombstones %d (%v), want %d", n, err, eligible)
		}
		got, err := del(t, scopeA, cutObj, w.held, `DELETE FROM app.stored_objects WHERE organization_id = $1::uuid`, w.orgA)
		if err != nil || got != int64(eligible) {
			t.Fatalf("purged %d (%v), want %d", got, err, eligible)
		}
		var left string
		if err := e.setup.QueryRow(ctx, `SELECT string_agg(s || '=' || n, ',' ORDER BY s) FROM (
  SELECT CASE WHEN organization_id = $2::uuid THEN 'b:' ELSE 'a:' END || state || CASE WHEN state = 'deleted' AND deleted_by = $3::uuid THEN ':held'
              WHEN state = 'deleted' AND deleted_at >= $4 THEN ':recent' ELSE '' END AS s, count(*) AS n
  FROM app.stored_objects WHERE organization_id IN ($1::uuid, $2::uuid) GROUP BY 1) x`, w.orgA, w.orgB, w.held, w.tObj).Scan(&left); err != nil ||
			left != "a:deleted:held=50,a:deleted:recent=50,a:deleting=1,a:pending=1,a:ready=1,b:deleted=50" {
			t.Errorf("remaining rows %q (%v)", left, err)
		}
	})

	t.Run("RT-8 revalidation: a hold added between count and delete preserves the row", func(t *testing.T) {
		var id, subject string
		if err := e.setup.QueryRow(ctx, `SELECT id::text, subject_user_id::text FROM audit.events WHERE organization_id = $1::uuid
  AND occurred_at < $2 AND subject_user_id IS NOT NULL ORDER BY occurred_at LIMIT 1`, w.orgA, w.tMid).Scan(&id, &subject); err != nil {
			t.Fatal(err)
		}
		if n, err := count(t, scopeA, cutMid, "none", `SELECT count(*) FROM audit.events WHERE id = $1::uuid`, id); err != nil || n != 1 {
			t.Fatalf("visible before the hold: %d (%v)", n, err)
		}
		got, err := del(t, scopeA, cutMid, subject, `DELETE FROM audit.events WHERE id = $1::uuid`, id)
		if err != nil || got != 0 || e.retCount(t, `id = $1::uuid`, id) != 1 {
			t.Errorf("held row deleted %d (%v)", got, err)
		}
		// The tombstone counterpart: an object hold (by its own id) added after the count. The retention login cannot read
		// deleted_by (its column grants are the minimal four), so the held tombstone is chosen by the superuser fixture.
		var obj string
		if err := e.setup.QueryRow(ctx, `SELECT id::text FROM app.stored_objects WHERE organization_id = $1::uuid AND state = 'deleted'
  AND deleted_by = $2::uuid ORDER BY id LIMIT 1`, w.orgA, w.held).Scan(&obj); err != nil {
			t.Fatal(err)
		}
		if n, err := count(t, scopeA, cutObj, "none", `SELECT count(*) FROM app.stored_objects WHERE id = $1::uuid`, obj); err != nil || n != 1 {
			t.Fatalf("tombstone visible without the hold: %d (%v)", n, err)
		}
		got, err = del(t, scopeA, cutObj, obj, `DELETE FROM app.stored_objects WHERE id = $1::uuid`, obj)
		if err != nil || got != 0 {
			t.Errorf("held tombstone deleted %d (%v)", got, err)
		}
		if _, err := count(t, scopeA, cutObj, "none", `SELECT count(*) FROM app.stored_objects WHERE deleted_by IS NOT NULL`); retState(err) != "42501" {
			t.Errorf("retention read deleted_by: %v (want 42501: minimal columns only)", err)
		}
	})
}
